def agent(observation,configuration=None):
 p=int(observation.get("player",0));step=min(int(observation.get("step",0)),718)
 if step==0:_ROUTE[p]=False
 elif step==1:
  try:
   opp=observation["farms"][1-p];inv=float(observation["market"]["inventory"]["WHEAT"]);_ROUTE[p]=len(opp["hands"])==0 and inv>=9986
  except Exception:_ROUTE[p]=False
 source=_AGGRESSIVE if _ROUTE.get(p,False) else _SAFE;action=copy.deepcopy(source[p][step]);action["hands"]=action.get("hands",[])[:len(observation["farms"][p]["hands"])]
 return action
act=agent
